Lemma kentry_cut_sound : forall segs E M M' spi lo hi ihi K,
  win_ok E spi lo hi ihi ->
  (forall x : word,
     ~ (bv_unsigned (ev E spi) + lo <= bv_unsigned x < bv_unsigned (ev E spi) + hi)%Z -> M' x = M x) ->
  mem_grows M M' ->
